function canonicalFamily(a,b){return `${Number(a)}x${Number(b)}`}
function conversionYield(sourceFamily,targetFamily){const s=parseFamilyDims(sourceFamily),t=parseFamilyDims(targetFamily);if(!s||!t)return 0;const [a,b]=s,[c,d]=t;if(c<=0||d<=0)return 0;const direct=Math.floor(a/c)*Math.floor(b/d),rotated=Math.floor(a/d)*Math.floor(b/c);return Math.max(direct,rotated)}
function conversionIsSmaller(sourceFamily,targetFamily){const y=conversionYield(sourceFamily,targetFamily);const s=parseFamilyDims(sourceFamily),t=parseFamilyDims(targetFamily);if(!y||!s||!t)return false;return t[0]*t[1]<s[0]*s[1]}
function conversionSuggestions(shortages){
  const out=[];
  for(const req of shortages||[]){
    const target=req.family;
    for(const x of state.lumber){
      if(x.category!=='raw'||Number(x.grade)!==Number(req.grade)||availableOf(x)<=0||!conversionIsSmaller(x.family,target))continue;
      const crossYield=conversionYield(x.family,target),rawLength=(Number(x.lengthFt)||0)*12,longitudinal=Math.floor(rawLength/Math.max(1,Number(req.cutLength)||1));
      const yieldPer=Math.max(0,crossYield*longitudinal*Math.max(1,Number(req.ripFactor)||1));
      if(!yieldPer)continue;
      out.push({target,sourceId:x.id,source:x.size,needed:req.missing,rawNeeded:Math.ceil(req.missing/yieldPer),yieldPer,label:req.label,crossYield});
    }
  }
  return out.sort((a,b)=>a.rawNeeded-b.rawNeeded||b.yieldPer-a.yieldPer)
}
function buildMaterialPlan(spec){
  const reqs=componentRequirements(spec),avail=Object.fromEntries(state.lumber.map(x=>[x.id,availableOf(x)])),alloc=[],shortages=[];let waste=0;
  const ordered=reqs.slice().sort((a,b)=>b.cutLength-a.cutLength||b.count-a.count);
  for(const req of ordered){let remain=req.count;
    // 1) usar primero piezas ya cortadas exactamente a la medida
    const finished=state.lumber.filter(x=>x.category==='finished'&&x.family===req.family&&Number(x.pieceLengthIn)===Number(req.cutLength)&&Number(x.grade)===Number(req.grade)&&avail[x.id]>0).sort((a,b)=>Number(b.grade)-Number(a.grade));
    for(const x of finished){if(remain<=0)break;const yp=Math.max(1,Number(req.ripFactor)||1),pieces=Math.min(avail[x.id],Math.ceil(remain/yp));if(!pieces)continue;const produced=Math.min(remain,pieces*yp);alloc.push({stockId:x.id,stock:x.size,grade:x.grade,component:req.label,cutLength:req.cutLength,rawPieces:pieces,yieldPerPiece:yp,produced,wasteIn:0,category:'finished'});avail[x.id]-=pieces;remain-=produced}
    // 2) después cortar materia prima de la familia correcta; nunca convertir 4x4/4x6 solo
    const opts=state.lumber.map(x=>{if(x.category!=='raw'||x.family!==req.family)return null;const raw=(Number(x.lengthFt)||8)*12,longitudinal=Math.floor(raw/req.cutLength),rip=Math.max(1,Number(req.ripFactor)||1),y=longitudinal*rip;return y>0?{x,raw,y,w:(raw-longitudinal*req.cutLength)/Math.max(1,y),exact:Number(x.grade)===req.grade}:null}).filter(Boolean).filter(o=>Number(o.x.grade)===Number(req.grade)&&avail[o.x.id]>0).sort((a,b)=>a.w-b.w||(b.exact-a.exact)||a.raw-b.raw);
    for(const o of opts){if(remain<=0)break;const pieces=Math.min(avail[o.x.id],Math.ceil(remain/o.y));if(!pieces)continue;const produced=Math.min(remain,pieces*o.y);alloc.push({stockId:o.x.id,stock:o.x.size,grade:o.x.grade,component:req.label,cutLength:req.cutLength,rawPieces:pieces,yieldPerPiece:o.y,produced,wasteIn:pieces*o.raw-produced*req.cutLength,category:'raw'});avail[o.x.id]-=pieces;remain-=produced;waste+=pieces*o.raw-produced*req.cutLength}
    if(remain>0)shortages.push({...req,missing:remain})
  }
  const agg={};for(const a of alloc)agg[a.stockId]=(agg[a.stockId]||0)+a.rawPieces;
  return {allocations:alloc,stockTotals:agg,shortages,wasteIn:waste,totalRaw:Object.values(agg).reduce((a,b)=>a+b,0),requirements:reqs,conversionSuggestions:conversionSuggestions(shortages)}
}
function buildOrderMaterialPlan(order){const products=orderProducts(order);return buildMaterialPlan({products})}
function reserveWood(order){const plan=buildOrderMaterialPlan(order);if(plan.shortages.length){order.materialPlan=plan;return false}for(const [id,n] of Object.entries(plan.stockTotals)){const w=lumberById(id);if(!w||availableOf(w)<n)return false}for(const [id,n] of Object.entries(plan.stockTotals))lumberById(id).reserved+=n;order.materialPlan=plan;order.materialReservation=plan.stockTotals;order.woodNeed=plan.totalRaw;save();return true}
function consumeReservedWood(order){for(const [id,n] of Object.entries(order.materialReservation||{})){const w=lumberById(id);if(!w)continue;w.qty=Math.max(0,w.qty-n);w.reserved=Math.max(0,w.reserved-n)}order.materialReservation={};save()}
function findFinished(sku){let f=state.finished.find(x=>x.sku===sku);if(!f){f={sku,qty:0,reserved:0};state.finished.push(f)}return f}
function parseProductMeasure(text){
  const m=String(text||'').match(/(\d+(?:\.\d+)?)\s*[×xX]\s*(\d+(?:\.\d+)?)/);
  return m?{length:Number(m[1]),width:Number(m[2])}:null;
}
function loadItemsFor(order){
  if(Array.isArray(order.loadItems)&&order.loadItems.length)return clone(order.loadItems);
  const products=orderProducts(order);if(products.length)return products.map(p=>{const r=palletTypeRules(p.type);return {name:p.name||`${p.length}×${p.width}`,length:Number(p.length),width:Number(p.width),quantity:Number(p.qty)||1,maxHeight:r.maxHeight,canRotate:r.canRotate,type:p.type}});
  const m=parseProductMeasure(order.product);if(!m)return [];return [{name:`${m.length}×${m.width}`,length:m.length,width:m.width,quantity:Number(order.qty)||1,maxHeight:20,canRotate:true,type:'4-way-runner'}]
}
function loadTotal(items){return (items||[]).reduce((n,x)=>n+(Number(x.quantity)||0),0)}


function orderMaterialSummary(o){
  try{
    const rows=pieceAvailability({products:orderProducts(o)});
    if(!rows.length)return '<span class="small">Sin piezas de madera.</span>';
    return `<div class="order-material-mini">${rows.map(r=>`<div><b>${pieceSizeLabel(r)} · #${r.grade}</b><br><span class="small">${r.count} piezas · inventario ${r.inventory} · faltante ${r.missing}</span></div>`).join('')}</div>`;
  }catch(err){console.error('Error en resumen de material',o?.id,err);return '<span class="small">Información pendiente de actualizar.</span>'}
}
function renderOrdenes(){
  const rows=Array.isArray(state.orders)?state.orders:[];
  const body=rows.map(o=>{
    try{
      const search=[o?.id,o?.clientOrder,o?.customer,o?.product].filter(Boolean).join(' ').toLowerCase();
      const products=orderProducts(o);
      const measures=products.length>1?`${products.length} medidas`:String(o?.product||products[0]?.name||'Sin medida');
      return `<tr data-order-row data-search="${search.replace(/"/g,'&quot;')}"><td><b>#${o?.id||'—'}</b>${o?.clientOrder?`<div class="small">Orden cliente: ${o.clientOrder}</div>`:''}</td><td>${o?.customer||'Sin cliente'}</td><td>${measures}</td><td>${Number(o?.qty)||0}</td><td>${pill(stageLabel(o?.stage||'waiting_material'),stageColor(o?.stage||'waiting_material'))}</td><td>${orderMaterialSummary(o)}</td><td><button class="btn secondary" data-order-spec="${o?.id||''}">Especificación</button></td></tr>`;
    }catch(err){console.error('Error dibujando orden',o?.id,err);return `<tr><td><b>#${o?.id||'—'}</b></td><td>${o?.customer||'Sin cliente'}</td><td colspan="5"><span class="small">Esta orden necesita actualizarse, pero no bloquea las demás.</span></td></tr>`}
  }).join('');
  return `<div class="toolbar"><button class="btn" data-action="newOrder">+ Nueva orden</button><input id="ordersSearch" class="search-input" placeholder="Buscar # interno, orden cliente o cliente"></div><div class="table-wrap"><table><thead><tr><th>Orden</th><th>Cliente</th><th>Producto</th><th>Cantidad</th><th>Etapa</th><th>Material que se utilizará</th><th>Detalle</th></tr></thead><tbody>${body||'<tr><td colspan="7">No hay órdenes.</td></tr>'}</tbody></table></div>`;
}

function renderInicio(){
  const active=state.orders.filter(o=>o.stage!=='completed').length, ready=state.orders.filter(o=>o.stage==='ready_load').length, prod=state.orders.filter(o=>['waiting_material','cutting','material_ready','building'].includes(o.stage)).length, low=state.lumber.filter(x=>x.qty-x.reserved<x.min).length;
  return `<div class="grid metrics">${metric('Órdenes activas',active,'En toda la operación')}${metric('Listas para cargar',ready,'Ya fabricadas y liberadas')}${metric('Producción en curso',prod,'Corte + fabricación')}${metric('Alertas de madera',low,'Debajo del mínimo disponible')}</div>
  <div class="section"><div class="section-head"><div><h2>Módulos</h2><p>Todos comparten las mismas órdenes; el prototipo permite moverlas por etapas.</p></div></div><div class="grid module-grid">${moduleCard('ordenes','＋','Órdenes','Crear una orden en dos pasos y reutilizar plantillas.')}${moduleCard('madera','▦','Inventario de madera','Materia prima, piezas listas y catálogo configurable.')}${moduleCard('conversion','⇄','Conversión de madera','Convertir manualmente cualquier medida a una medida inferior cuando tú lo autorices.')}${moduleCard('produccion','✂','Producción / Corte','Reservar madera, iniciar corte y liberar material.')}${moduleCard('fabricacion','⚒','Fabricación','Recibir aviso, armar pallets y liberarlos.')}${moduleCard('terminados','▣','Inventario de pallets','Producto terminado y reservado.')}${moduleCard('carga','▰','Carga y despacho','Optimizar, cargar, evidencia, firma y salida.')}${moduleCard('reportes','▥','Reportes','Resumen operativo sin crear menús innecesarios.')}</div></div>
  <div class="section grid two-col"><div class="card"><div class="section-head"><div><h2>Flujo real de una orden</h2><p>Cada botón mueve la misma orden al siguiente módulo.</p></div></div><div class="timeline"><span class="node">Inventario</span><span class="arrow">→</span><span class="node">Corte</span><span class="arrow">→</span><span class="node">Material listo</span><span class="arrow">→</span><span class="node">Fabricación</span><span class="arrow">→</span><span class="node">Carga</span><span class="arrow">→</span><span class="node">Historial</span></div><div style="height:14px"></div><button class="btn" data-go="ordenes">Crear / revisar órdenes</button></div><div class="card"><h2 style="font-size:17px;margin-top:0">Avisos automáticos</h2>${state.notifications.slice(0,4).map(n=>`<div class="notification ${n.kind==='ok'?'ok':''}" style="margin-bottom:8px">${n.text}</div>`).join('')||'<div class="small">Sin avisos.</div>'}</div></div>${pendingPiecesHomeHtml()}`
}
function render(){
  try{
    if(!views[currentView])currentView='inicio';
    const [t,s]=views[currentView];el.title.textContent=t;el.subtitle.textContent=s;
    const renderer=({inicio:renderInicio,ordenes:renderOrdenes,madera:renderMadera,conversion:renderConversion,produccion:renderProduccion,fabricacion:renderFabricacion,terminados:renderTerminados,carga:renderCarga,reportes:renderReportes,resumen:renderResumen,historial:renderHistorial,configuracion:renderConfiguracion})[currentView];
    el.content.innerHTML=renderer?renderer():renderInicio();bindDynamic();applyTheme();
  }catch(err){
    console.error('Error al dibujar la vista',currentView,err);
    el.content.innerHTML=`<div class="card"><h2>No se pudo cargar esta vista</h2><p class="small">Se detectó un dato antiguo o incompatible. La aplicación sigue disponible.</p><button class="btn" id="recoverView">Volver al inicio</button></div>`;
    document.getElementById('recoverView')?.addEventListener('click',()=>{currentView='inicio';location.hash='inicio';render()});applyTheme();
  }
}
function renderMadera(){const raw=state.lumber.filter(x=>x.category==='raw'),finished=state.lumber.filter(x=>x.category==='finished');const rows=list=>list.map(x=>{const a=availableOf(x);return `<tr><td><b>${x.size}</b><div class="small">${x.family}</div></td><td><b>#${x.grade}</b></td><td>${x.qty}</td><td>${x.reserved||0}</td><td>${a}</td><td>${x.min||0}</td><td>${a<(x.min||0)?pill('Bajo','yellow'):pill('Bien','green')}</td></tr>`}).join('');return `<div class="toolbar"><button class="btn" data-action="receiveWood">+ Recibir madera</button><button class="btn secondary" data-action="addMaterial">+ Agregar tipo de madera</button><button class="btn secondary" data-go="conversion">Conversión manual</button></div><div class="section-head"><div><h2>Materia prima</h2><p>2×4, 2×6, 4×4, 4×6 y cualquier medida que agregues al catálogo.</p></div></div><div class="table-wrap"><table><thead><tr><th>Medida</th><th>Calidad</th><th>Existencia</th><th>Reservado</th><th>Disponible</th><th>Mínimo</th><th>Estado</th></tr></thead><tbody>${rows(raw)}</tbody></table></div><div class="section-head section"><div><h2>Piezas ya cortadas</h2><p>El planificador usa estas piezas primero antes de cortar madera larga.</p></div></div><div class="table-wrap"><table><thead><tr><th>Pieza lista</th><th>Calidad</th><th>Existencia</th><th>Reservado</th><th>Disponible</th><th>Mínimo</th><th>Estado</th></tr></thead><tbody>${rows(finished)||'<tr><td colspan="7">Sin piezas listas.</td></tr>'}</tbody></table></div><div class="section notification info"><b>Regla:</b> producción usa primero piezas listas; después corta 2×4/2×6 de inventario. Ninguna medida se convierte automáticamente; las conversiones siempre requieren tu confirmación.</div>`}
function wasteMonthKey(ts){const d=new Date(ts||Date.now());return `${d.getFullYear()}-${String(d.getMonth()+1).padStart(2,'0')}`}
function wasteMonthLabel(key){const [y,m]=String(key).split('-').map(Number);return new Date(y,m-1,1).toLocaleDateString('es-US',{month:'long',year:'numeric'})}
function wasteMonthlyTotals(){const totals={};for(const w of state.wasteLog||[]){const k=w.month||wasteMonthKey(w.createdAt);totals[k]=(totals[k]||0)+(Number(w.wasteTotalIn)||0)}return Object.entries(totals).sort((a,b)=>b[0].localeCompare(a[0]))}
function cutRowsHtml(){return `<div id="convCutRows" class="conversion-cut-list"><div class="board-editor-head"><b>Patrón de cortes por cada pieza fuente</b><button type="button" class="btn ghost" data-add-cut>+ Agregar corte</button></div><div class="conversion-cut-row" data-cut-row><label><span>Largo (in)</span><input data-cut-length type="number" min="0.125" step="0.125" value="48"></label><label><span>Piezas de este largo</span><input data-cut-qty type="number" min="1" step="1" value="2"></label><button type="button" class="remove-board" data-remove-cut aria-label="Eliminar corte">×</button></div></div>`}
function wasteHistoryHtml(){const months=wasteMonthlyTotals(),recent=(state.wasteLog||[]).slice().sort((a,b)=>new Date(b.createdAt)-new Date(a.createdAt)).slice(0,30);return `<div class="section"><div class="section-head"><div><h2>Desperdicio mensual</h2><p>Se suma automáticamente solo a partir de los cortes de largo guardados.</p></div></div><div class="grid metrics">${months.length?months.slice(0,6).map(([k,v])=>metric(wasteMonthLabel(k),`${Number(v.toFixed(3))} in`,'Desperdicio acumulado')).join(''):metric('Este mes','0 in','Aún no hay desperdicio registrado')}</div></div><div class="section"><div class="section-head"><div><h2>Historial de desperdicio</h2><p>Cada corte conserva el sobrante por pieza y el total de la operación.</p></div></div><div class="table-wrap"><table><thead><tr><th>Fecha</th><th>Material fuente</th><th>Cantidad</th><th>Patrón</th><th>Usado / pieza</th><th>Sobrante / pieza</th><th>Desperdicio total</th></tr></thead><tbody>${recent.map(w=>`<tr><td>${new Date(w.createdAt).toLocaleString('es-US')}</td><td><b>${w.sourceSize}</b></td><td>${w.sourceQty}</td><td>${(w.cuts||[]).map(c=>`${c.qty}×${c.lengthIn}&quot;`).join(' + ')}</td><td>${w.usedPerSourceIn} in</td><td>${w.wastePerSourceIn} in</td><td><b>${w.wasteTotalIn} in</b></td></tr>`).join('')||'<tr><td colspan="7">Todavía no hay cortes registrados.</td></tr>'}</tbody></table></div></div>`}
function renderConversion(){const sources=state.lumber.filter(x=>availableOf(x)>0&&parseFamilyDims(x.family));const families=[...new Set(state.lumber.map(x=>x.family).filter(f=>parseFamilyDims(f)))].sort((a,b)=>{const A=parseFamilyDims(a),B=parseFamilyDims(b);return (A[0]*A[1])-(B[0]*B[1])});return `<div class="grid metrics">${metric('Materiales disponibles',sources.length,'Materia prima y piezas ya cortadas')}${metric('Operaciones','2','Cortar largo o convertir sección')}${metric('Corte múltiple','Sí','Varios largos desde una misma pieza')}${metric('Desperdicio',`${Number(wasteMonthlyTotals()[0]?.[1]||0).toFixed(2)} in`,'Mes más reciente registrado')}</div><div class="section card"><h2 style="font-size:17px;margin-top:0">Conversión y corte de madera</h2><p class="small">En corte de largo puedes crear varios tamaños desde la misma pieza madre. El sistema suma los largos, muestra el sobrante y guarda ese desperdicio. En conversión de sección, tú sigues indicando manualmente el rendimiento final.</p><div class="form-grid"><label><span>Operación</span><select id="convOperation"><option value="length">Cortar largo</option><option value="section">Convertir sección</option></select></label><label><span>Madera fuente</span><select id="convSource">${sources.map(x=>`<option value="${x.id}">${x.size} · #${x.grade} · disp. ${availableOf(x)}</option>`).join('')}</select></label><label><span>Cantidad de piezas fuente</span><input id="convQty" type="number" min="1" step="1" value="1"></label><label><span>Trabajador / responsable</span><select id="convWorker"><option value="">— Seleccionar trabajador —</option>${activeWorkers().map(w=>`<option value="${w.id}">${w.name}</option>`).join('')}</select></label><div class="toolbar" style="align-items:end"><button type="button" class="btn secondary" data-action="addWorker">+ Agregar trabajador</button></div><label id="convYieldWrap" style="display:none"><span>Piezas destino por cada fuente</span><input id="convYield" type="number" min="1" step="1" value="2"></label></div><div id="convLengthFields">${cutRowsHtml()}<div class="small">Ejemplo: 40 + 26 + 30 = 96 in, sobrante 0. O 38 + 24 + 32 = 94 in, sobrante 2 in por cada pieza fuente.</div></div><div id="convSectionFields" style="display:none"><div class="form-grid"><label><span>Medida destino del catálogo</span><select id="convTargetFamily"><option value="">— Escribir otra medida —</option>${families.map(f=>`<option value="${f}">${f.replace('x','×')}</option>`).join('')}</select></label><label><span>Destino lado A</span><input id="convTargetA" type="number" min="0.125" step="0.125" value="1"></label><label><span>Destino lado B</span><input id="convTargetB" type="number" min="0.125" step="0.125" value="4"></label></div><div class="small">Aquí tú decides el rendimiento. Ejemplo: 2×4 → 0.5×4 = 3 piezas. El sistema agrega solo esas 3 y no registra el resto como desperdicio.</div></div><div id="convPreview" class="notification info"></div><div class="dialog-actions"><button class="btn" data-action="convertWood">Guardar operación</button></div></div>${wasteHistoryHtml()}`}
function renderProduccion(){const rows=state.orders.filter(o=>['waiting_material','cutting','material_ready'].includes(o.stage));return `<div class="toolbar"><button class="btn secondary" data-go="ordenes">Ir a Órdenes</button><input id="productionSearch" class="search-input" placeholder="Buscar # interno, orden cliente o cliente"></div><div class="table-wrap"><table><thead><tr><th>Orden</th><th>Cliente</th><th>Producto</th><th>Cantidad</th><th>Etapa</th><th>Piezas requeridas / inventario</th><th>Acción</th></tr></thead><tbody>${rows.map(o=>{const status=pieceAvailability({products:orderProducts(o)}),ready=status.every(r=>r.ready),action=o.stage==='waiting_material'?(ready?`<button class="btn" data-cut-start="${o.id}">Reservar piezas listas</button>`:`<span class="small">Pendiente: faltan piezas</span>`):o.stage==='cutting'?`<button class="btn" data-cut-ready="${o.id}">Confirmar piezas listas</button>`:`<span class="small">Esperando fabricación</span>`;const search=[o.id,o.clientOrder,o.customer,o.product].filter(Boolean).join(' ').toLowerCase();return `<tr data-production-row data-search="${search.replace(/"/g,'&quot;')}"><td><b>#${o.id}</b>${o.clientOrder?`<div class="small">Cliente: ${o.clientOrder}</div>`:''}</td><td>${o.customer}</td><td>${o.product}</td><td>${o.qty}</td><td>${pill(stageLabel(o.stage),stageColor(o.stage))}</td><td>${orderMaterialSummary(o)}</td><td>${action}</td></tr>`}).join('')||'<tr><td colspan="7">No hay órdenes en esta etapa.</td></tr>'}</tbody></table></div><div class="section card"><b>Producción / Corte</b><p class="small">Esta versión solo controla las piezas terminadas que necesita cada orden y compara contra inventario. No decide de qué madera larga obtenerlas ni genera un plan de corte. Ese cálculo quedará para el optimizador de órdenes seleccionadas.</p></div>`}
function renderFabricacion(){const rows=state.orders.filter(o=>['material_ready','building'].includes(o.stage));return `<div class="grid metrics">${metric('Material listo',rows.filter(o=>o.stage==='material_ready').length,'Puede recogerlo el armador')}${metric('En fabricación',rows.filter(o=>o.stage==='building').length,'Trabajo activo')}${metric('Listas para carga',state.orders.filter(o=>o.stage==='ready_load').length,'Ya fabricadas')}${metric('Avisos',state.notifications.length,'Eventos recientes')}</div><div class="section table-wrap"><table><thead><tr><th>Orden</th><th>Cliente</th><th>Producto</th><th>Cantidad</th><th>Estado</th><th>Acción</th></tr></thead><tbody>${rows.map(o=>`<tr><td>#${o.id}</td><td>${o.customer}</td><td>${o.product}</td><td>${o.qty}</td><td>${pill(stageLabel(o.stage),stageColor(o.stage))}</td><td>${o.stage==='material_ready'?`<button class="btn" data-build-start="${o.id}">Iniciar fabricación</button>`:`<button class="btn" data-build-ready="${o.id}">Terminar y liberar</button>`}</td></tr>`).join('')||'<tr><td colspan="6">No hay órdenes en fabricación.</td></tr>'}</tbody></table></div><div class="section notification ok"><b>Aviso automático:</b> cuando Corte libera material, Fabricación lo ve aquí sin que nadie tenga que ir a avisar personalmente.</div>`}
function renderTerminados(){const total=state.finished.reduce((s,x)=>s+x.qty,0),res=state.finished.reduce((s,x)=>s+x.reserved,0);return `<div class="grid metrics">${metric('Fabricados',total,'Inventario actual')}${metric('Reservados',res,'Asignados a órdenes')}${metric('Disponibles',total-res,'Sin reservar')}${metric('Listos para carga',state.orders.filter(o=>o.stage==='ready_load').reduce((s,o)=>s+o.qty,0),'Pallets liberados')}</div><div class="section table-wrap"><table><thead><tr><th>SKU</th><th>Existencia</th><th>Reservado</th><th>Disponible</th></tr></thead><tbody>${state.finished.map(x=>`<tr><td><b>${x.sku}</b></td><td>${x.qty}</td><td>${x.reserved}</td><td>${x.qty-x.reserved}</td></tr>`).join('')}</tbody></table></div>`}
function shipPill(o){if(o.shipping==='pickup')return pill('Recogida del cliente','blue');if(o.stage==='transit')return pill('En tránsito','pink');return pill('Envío de fábrica','yellow')}
function renderCarga(){const rows=state.orders.filter(o=>o.stage!=='completed');return `<div class="toolbar"><button class="btn secondary" id="openLoadMaster">Abrir LoadMaster AI</button><input id="loadSearch" class="search-input" placeholder="Buscar # interno, orden cliente o cliente"><select><option>Todos</option><option>Envío de fábrica</option><option>Recogida del cliente</option><option>En tránsito</option></select></div><div class="grid two-col"><div><h2 style="font-size:16px">Pedidos y planificación de carga</h2>${rows.map(o=>{const ready=['ready_load','loading','transit'].includes(o.stage);const search=[o.id,o.clientOrder,o.customer,o.product].filter(Boolean).join(' ').toLowerCase();let action='';if(o.stage==='transit')action=`<button class="btn" data-transit-done="${o.id}">Marcar entregado</button>`;else if(ready)action=`<button class="btn" data-load-order="${o.id}">${o.stage==='loading'?'Continuar carga':(o.shipping==='pickup'?'Iniciar recogida':'Optimizar / iniciar carga')}</button>`;else action=`<button class="btn secondary" data-plan-load="${o.id}">Planear en LoadMaster</button><div class="small" style="margin-top:6px">Aún no se puede despachar: ${stageLabel(o.stage)}.</div>`;return `<div class="card order-card" data-load-card data-search="${search.replace(/"/g,'&quot;')}"><div class="order-card-top"><div>${shipPill(o)}<h3 style="margin:9px 0 3px">${o.customer}</h3><div class="small">Orden interna #${o.id}${o.clientOrder?` · Orden cliente ${o.clientOrder}`:''}</div><div class="small">${o.qty} pallets · ${o.product}</div>${progressFor(o.stage)}</div><div style="text-align:right"><div class="small">Estado</div><b>${stageLabel(o.stage)}</b><div style="height:8px"></div>${action}</div></div></div>`}).join('')||'<div class="empty-state">No hay pedidos.</div>'}</div><aside><div class="card"><h2 style="font-size:16px;margin-top:0">Planificación anticipada</h2><p class="small">Una orden aparece aquí desde que se crea. LoadMaster puede planearla antes de fabricar, pero los botones de carga y despacho solo se habilitan cuando Fabricación la libera.</p></div><div class="card" style="margin-top:12px"><h2 style="font-size:16px;margin-top:0">Colores de despacho</h2><div>${pill('Envío de fábrica','yellow')}<div class="small" style="margin:5px 4px 12px">La fábrica pone tráiler y chofer.</div>${pill('Recogida del cliente','blue')}<div class="small" style="margin:5px 4px 12px">El cliente llega con su propio tráiler.</div>${pill('En tránsito','pink')}<div class="small" style="margin:5px 4px">El chofer de la fábrica va camino al cliente.</div></div></div></aside></div>`}
function localDayKey(value=new Date()){const d=value instanceof Date?value:new Date(value);if(Number.isNaN(d.getTime()))return '';const y=d.getFullYear(),m=String(d.getMonth()+1).padStart(2,'0'),day=String(d.getDate()).padStart(2,'0');return `${y}-${m}-${day}`}
function activeWorkers(){return (state.workers||[]).filter(w=>w&&w.active!==false&&String(w.name||'').trim())}
function workerName(id){return (state.workers||[]).find(w=>w.id===id)?.name||'Sin trabajador'}
function todayProductionEntries(){const key=localDayKey();return (state.productionLog||[]).filter(x=>x&&localDayKey(x.createdAt)===key)}
function dailyCutSummary(){const map=new Map();for(const e of todayProductionEntries().filter(x=>x.type==='length-cut'))for(const out of e.outputs||[]){const k=`${out.family}|${out.lengthIn}|${e.grade}`;const cur=map.get(k)||{family:out.family,lengthIn:Number(out.lengthIn)||0,grade:Number(e.grade)||0,qty:0};cur.qty+=Number(out.qty)||0;map.set(k,cur)}return [...map.values()].sort((a,b)=>a.family.localeCompare(b.family)||a.lengthIn-b.lengthIn||a.grade-b.grade)}
function workerDailySummary(){const map=new Map();for(const e of todayProductionEntries().filter(x=>x.type==='length-cut')){const id=e.workerId||'',cur=map.get(id)||{id,name:workerName(id),qty:0,jobs:0};cur.jobs+=1;cur.qty+=(e.outputs||[]).reduce((a,b)=>a+(Number(b.qty)||0),0);map.set(id,cur)}return [...map.values()].sort((a,b)=>b.qty-a.qty)}
function renderResumen(){const rows=dailyCutSummary(),workers=workerDailySummary(),entries=todayProductionEntries().filter(x=>x.type==='length-cut').slice().sort((a,b)=>new Date(b.createdAt)-new Date(a.createdAt));const total=rows.reduce((a,b)=>a+b.qty,0);return `<div class="grid metrics">${metric('Piezas cortadas hoy',total,'Total de piezas terminadas')}${metric('Medidas diferentes',rows.length,'Cortes registrados hoy')}${metric('Trabajadores activos',activeWorkers().length,'Disponibles para seleccionar')}${metric('Operaciones de corte',entries.length,'Guardadas hoy')}</div><div class="section grid two-col"><div class="card"><div class="section-head"><div><h2>Producción de hoy por medida</h2><p>Se actualiza cada vez que guardas un corte de largo.</p></div></div><div class="table-wrap"><table><thead><tr><th>Medida cortada</th><th>Calidad</th><th>Piezas</th></tr></thead><tbody>${rows.map(r=>`<tr><td><b>${r.family.replace('x','×')} × ${r.lengthIn} in</b></td><td>#${r.grade}</td><td><b>${r.qty}</b></td></tr>`).join('')||'<tr><td colspan="3">Todavía no se han registrado cortes hoy.</td></tr>'}</tbody></table></div></div><div class="card"><div class="section-head"><div><h2>Por trabajador</h2><p>Quién cortó y cuántas piezas realizó hoy.</p></div></div><div class="status-list">${workers.map(w=>`<div class="status-row"><span class="dot"></span><div><b>${w.name}</b><div class="small">${w.jobs} operación${w.jobs===1?'':'es'}</div></div><b>${w.qty} piezas</b></div>`).join('')||'<div class="small">Sin actividad registrada.</div>'}</div></div></div><div class="section card"><div class="section-head"><div><h2>Trabajadores</h2><p>Agrega trabajadores para seleccionarlos al guardar cada corte.</p></div><button class="btn" data-action="addWorker">+ Agregar trabajador</button></div><div class="table-wrap"><table><thead><tr><th>Nombre</th><th>Estado</th><th>Acción</th></tr></thead><tbody>${(state.workers||[]).map(w=>`<tr><td><b>${w.name}</b></td><td>${w.active!==false?pill('Activo','green'):pill('Inactivo','yellow')}</td><td><button class="btn ghost" data-toggle-worker="${w.id}">${w.active!==false?'Desactivar':'Activar'}</button></td></tr>`).join('')||'<tr><td colspan="3">No hay trabajadores. Agrega el primero.</td></tr>'}</tbody></table></div></div><div class="section"><div class="section-head"><div><h2>Detalle de cortes de hoy</h2><p>Historial del día con trabajador y patrón realizado.</p></div></div><div class="table-wrap"><table><thead><tr><th>Hora</th><th>Trabajador</th><th>Fuente</th><th>Resultado</th><th>Desperdicio</th></tr></thead><tbody>${entries.map(e=>`<tr><td>${new Date(e.createdAt).toLocaleTimeString('es-US',{hour:'numeric',minute:'2-digit'})}</td><td><b>${workerName(e.workerId)}</b></td><td>${e.sourceQty} × ${e.sourceSize}</td><td>${(e.outputs||[]).map(o=>`${o.qty} × ${o.family.replace('x','×')}×${o.lengthIn}`).join(', ')}</td><td>${Number(e.wasteTotalIn||0)} in</td></tr>`).join('')||'<tr><td colspan="5">Sin cortes registrados hoy.</td></tr>'}</tbody></table></div></div>`}
function renderReportes(){const completed=state.history.length;return `<div class="grid metrics">${metric('Órdenes activas',state.orders.filter(o=>o.stage!=='completed').length,'Operación actual')}${metric('Pallets terminados',state.finished.reduce((s,x)=>s+x.qty,0),'Inventario')}${metric('Despachos históricos',completed,'En este demo')}${metric('Retención',state.settings.historyDays+' días','Configurable')}</div><div class="section grid two-col"><div class="card"><h2 style="font-size:16px;margin-top:0">Resumen por etapa</h2><div class="status-list">${['waiting_material','cutting','material_ready','building','ready_load','transit'].map(s=>`<div class="status-row"><span class="dot"></span><div>${stageLabel(s)}</div><b>${state.orders.filter(o=>o.stage===s).length}</b></div>`).join('')}</div></div><div class="card"><h2 style="font-size:16px;margin-top:0">Idea de producción sumario</h2><p class="small">Este módulo concentra la información de productividad sin obligar a crear un menú separado para cada reporte.</p></div></div>`}
function renderHistorial(){return `<div class="toolbar"><label class="small">Retención <select id="historyDays"><option value="30" ${state.settings.historyDays===30?'selected':''}>30 días</option><option value="60" ${state.settings.historyDays===60?'selected':''}>60 días</option><option value="90" ${state.settings.historyDays===90?'selected':''}>90 días</option></select></label></div><div class="table-wrap"><table><thead><tr><th>Pedido</th><th>Cliente</th><th>Tipo</th><th>Completado</th><th>Evidencia</th></tr></thead><tbody>${state.history.map(h=>`<tr><td>#${h.id}${h.clientOrder?`<div class="small">Cliente: ${h.clientOrder}</div>`:''}</td><td>${h.customer}</td><td>${h.shipping==='pickup'?'Recogida cliente':'Envío fábrica'}</td><td>${h.completed}</td><td>${h.evidence}</td></tr>`).join('')||'<tr><td colspan="5">Sin historial.</td></tr>'}</tbody></table></div><div class="section notification">El prototipo guarda el historial en el navegador. En la plataforma real, la retención podrá archivar o purgar automáticamente según la política que se decida.</div>`}
function renderConfiguracion(){const t=state.settings.theme||'system';return `<div class="grid two-col"><section class="card"><h2 style="margin-top:0;font-size:17px">Apariencia</h2><p class="small">El tema se aplica a toda Pallet Operations y se entrega también a LoadMaster AI.</p><label class="theme-setting"><span>Tema</span><select id="settingsTheme"><option value="light" ${t==='light'?'selected':''}>Claro</option><option value="dark" ${t==='dark'?'selected':''}>Oscuro</option><option value="system" ${t==='system'?'selected':''}>Automático (sistema)</option></select></label><div class="theme-preview-row"><div class="theme-swatch light-swatch">Claro</div><div class="theme-swatch dark-swatch">Oscuro</div></div></section><section class="card"><h2 style="margin-top:0;font-size:17px">Reglas visuales de pallets</h2><p class="small">2-Way Runner usa runners rectos. 4-Way Runner usa runners con muescas. Block se trata siempre como 4-Way. Crates muestran únicamente su pallet base; la caja de plywood no se dibuja todavía.</p></section></div>`}

function navigate(v){currentView=v;document.querySelectorAll('.nav-btn').forEach(b=>b.classList.toggle('active',b.dataset.view===v));document.getElementById('sidebar').classList.remove('open');render()}
function openDialog(title,subtitle,body){el.dialog.classList.remove('fullscreen');el.dialogTitle.textContent=title;el.dialogSubtitle.textContent=subtitle||'';el.dialogBody.innerHTML=body;if(!el.dialog.open)el.dialog.showModal()}
function openFullDialog(title,subtitle,body){el.dialog.classList.add('fullscreen');el.dialogTitle.textContent=title;el.dialogSubtitle.textContent=subtitle||'';el.dialogBody.innerHTML=body;if(!el.dialog.open)el.dialog.showModal()}
function closeDialog(){el.dialog.close();el.dialog.classList.remove('fullscreen')}
function bindDynamic(){
  document.querySelectorAll('[data-go]').forEach(x=>x.onclick=()=>navigate(x.dataset.go));
  document.querySelectorAll('[data-cut-start]').forEach(x=>x.onclick=()=>startCut(x.dataset.cutStart));
  document.querySelectorAll('[data-cut-ready]').forEach(x=>x.onclick=()=>finishCut(x.dataset.cutReady));
  document.querySelectorAll('[data-build-start]').forEach(x=>x.onclick=()=>startBuild(x.dataset.buildStart));
  document.querySelectorAll('[data-build-ready]').forEach(x=>x.onclick=()=>finishBuild(x.dataset.buildReady));
  document.querySelectorAll('[data-load-order]').forEach(x=>x.onclick=()=>openLoadOrder(x.dataset.loadOrder));
  document.querySelectorAll('[data-plan-load]').forEach(x=>x.onclick=()=>openLoadPreparation(x.dataset.planLoad));
  document.querySelectorAll('[data-order-spec]').forEach(x=>x.onclick=()=>openOrderSpecification(x.dataset.orderSpec));
  document.querySelectorAll('[data-transit-done]').forEach(x=>x.onclick=()=>completeDelivery(x.dataset.transitDone));
  document.getElementById('openLoadMaster')?.addEventListener('click',openLoadMaster);
  document.querySelector('[data-action="receiveWood"]')?.addEventListener('click',receiveWoodDialog);
  document.querySelector('[data-action="addMaterial"]')?.addEventListener('click',addMaterialDialog);
  document.querySelector('[data-action="convertWood"]')?.addEventListener('click',convertWoodFromView);
  document.getElementById('convOperation')?.addEventListener('change',()=>{syncConversionOperationFields();updateConversionPreview()});document.getElementById('convSource')?.addEventListener('change',updateConversionPreview);document.getElementById('convQty')?.addEventListener('input',updateConversionPreview);document.getElementById('convYield')?.addEventListener('input',updateConversionPreview);document.getElementById('convTargetFamily')?.addEventListener('change',e=>{const d=parseFamilyDims(e.target.value);if(d){document.getElementById('convTargetA').value=d[0];document.getElementById('convTargetB').value=d[1]}updateConversionPreview()});document.getElementById('convTargetA')?.addEventListener('input',updateConversionPreview);document.getElementById('convTargetB')?.addEventListener('input',updateConversionPreview);document.querySelector('[data-add-cut]')?.addEventListener('click',addCutRow);document.querySelectorAll('[data-cut-row] input').forEach(x=>x.addEventListener('input',updateConversionPreview));document.querySelectorAll('[data-remove-cut]').forEach(x=>x.addEventListener('click',removeCutRow));if(currentView==='conversion'){syncConversionOperationFields();updateConversionPreview()}
  document.querySelector('[data-action="physicalCount"]')?.addEventListener('click',()=>toast('Prototipo: aquí se capturaría un conteo físico.'));
  document.querySelector('[data-action="newOrder"]')?.addEventListener('click',newOrderDialog);
  document.querySelector('[data-action="autoPlan"]')?.addEventListener('click',()=>toast('El optimizador de corte se aplicará después solo a las órdenes que selecciones.'));document.querySelector('[data-action="addWorker"]')?.addEventListener('click',addWorkerDialog);document.querySelectorAll('[data-toggle-worker]').forEach(x=>x.addEventListener('click',()=>{const w=(state.workers||[]).find(v=>v.id===x.dataset.toggleWorker);if(w){w.active=w.active===false;save();render()}}));
  document.getElementById('historyDays')?.addEventListener('change',e=>{state.settings.historyDays=Number(e.target.value);save();toast('Retención actualizada a '+e.target.value+' días.')});document.getElementById('settingsTheme')?.addEventListener('change',e=>{setTheme(e.target.value);toast('Apariencia actualizada.')});
  document.getElementById('ordersSearch')?.addEventListener('input',e=>filterBySearch('[data-order-row]',e.target.value));
  document.getElementById('productionSearch')?.addEventListener('input',e=>filterBySearch('[data-production-row]',e.target.value));
  document.getElementById('loadSearch')?.addEventListener('input',e=>filterBySearch('[data-load-card]',e.target.value));
}
function filterBySearch(selector,value){const q=String(value||'').trim().toLowerCase();document.querySelectorAll(selector).forEach(el=>{el.style.display=!q||String(el.dataset.search||'').includes(q)?'':'none'})}
function addWorkerDialog(){openDialog('Agregar trabajador','Disponible para cortes y resúmenes diarios',`<div class="form-grid"><label><span>Nombre del trabajador</span><input id="workerName" autocomplete="off" placeholder="Ej. Juan Pérez"></label></div><div class="dialog-actions"><button class="btn secondary" id="workerCancel">Cancelar</button><button class="btn" id="workerSave">Agregar trabajador</button></div>`);document.getElementById('workerCancel').onclick=closeDialog;document.getElementById('workerSave').onclick=()=>{const name=String(document.getElementById('workerName').value||'').trim();if(!name){toast('Escribe el nombre del trabajador.');return}if((state.workers||[]).some(w=>String(w.name||'').trim().toLowerCase()===name.toLowerCase())){toast('Ese trabajador ya existe.');return}state.workers=Array.isArray(state.workers)?state.workers:[];state.workers.push({id:'EMP-'+Date.now(),name,active:true});save();closeDialog();toast('Trabajador agregado.');render()}}
function receiveWoodDialog(){openDialog('Recibir madera','Entrada de materia prima',`<div class="form-grid"><label><span>Medida</span><select id="rwSize">${state.lumber.map(x=>`<option value="${x.id}">${x.size} · calidad #${x.grade}</option>`).join('')}</select></label><label><span>Cantidad de piezas</span><input id="rwQty" type="number" min="1" value="100"></label></div><div class="dialog-actions"><button type="button" class="btn secondary" id="rwCancel">Cancelar</button><button type="button" class="btn" id="rwSave">Recibir</button></div>`);document.getElementById('rwCancel').onclick=closeDialog;document.getElementById('rwSave').onclick=()=>{const l=lumberById(document.getElementById('rwSize').value);l.qty+=Number(document.getElementById('rwQty').value)||0;save();closeDialog();toast('Madera recibida y disponible.');render()}}
function addMaterialDialog(){openDialog('Agregar tipo de madera','Catálogo configurable',`<div class="form-grid"><label><span>Categoría</span><select id="amCategory"><option value="raw">Materia prima</option><option value="finished">Pieza ya cortada</option></select></label><label><span>Familia</span><input id="amFamily" placeholder="2x4, 2x6, 4x4, 4x6, 3x4..."></label><label><span>Largo</span><input id="amLength" type="number" min="1" value="8"></label><label><span>Unidad del largo</span><select id="amUnit"><option value="ft">pies (materia prima)</option><option value="in">pulgadas (pieza lista)</option></select></label><label><span>Calidad</span><select id="amGrade">${[1,2,3,4].map(g=>`<option value="${g}">#${g}</option>`).join('')}</select></label><label><span>Cantidad inicial</span><input id="amQty" type="number" min="0" value="0"></label><label><span>Mínimo</span><input id="amMin" type="number" min="0" value="0"></label></div><div class="dialog-actions"><button class="btn secondary" id="amCancel">Cancelar</button><button class="btn" id="amSave">Agregar al catálogo</button></div>`);document.getElementById('amCancel').onclick=closeDialog;document.getElementById('amSave').onclick=()=>{const category=document.getElementById('amCategory').value,family=document.getElementById('amFamily').value.trim().toLowerCase();if(!family){toast('Indica la familia de madera.');return}const len=Math.max(1,Number(document.getElementById('amLength').value)||1),grade=Number(document.getElementById('amGrade').value)||2,qty=Math.max(0,Number(document.getElementById('amQty').value)||0),min=Math.max(0,Number(document.getElementById('amMin').value)||0),id='MAT-'+Date.now();const item={id,category,family,grade,qty,reserved:0,min,size:`${family.replace('x','×')} × ${len} ${category==='raw'?'ft':'in'}${category==='finished'?' · pieza lista':''}`};if(category==='raw')item.lengthFt=len;else item.pieceLengthIn=len;state.lumber.push(item);save();closeDialog();toast('Tipo de madera agregado.');render()}}
function selectedConversionTarget(){const family=document.getElementById('convTargetFamily')?.value,d=family?parseFamilyDims(family):null;if(d)return canonicalFamily(d[0],d[1]);const a=Number(document.getElementById('convTargetA')?.value),b=Number(document.getElementById('convTargetB')?.value);return a>0&&b>0?canonicalFamily(a,b):''}
function sourceLengthIn(src){return src?.category==='raw'?Math.max(0,Number(src.lengthFt)||0)*12:Math.max(0,Number(src?.pieceLengthIn)||0)}
function sectionFitsInside(sourceFamily,targetFamily){const s=parseFamilyDims(sourceFamily),t=parseFamilyDims(targetFamily);if(!s||!t)return false;const [a,b]=s,[c,d]=t,direct=c<=a&&d<=b,rotated=c<=b&&d<=a,same=(c===a&&d===b)||(c===b&&d===a);return (direct||rotated)&&!same}
function syncConversionOperationFields(){const op=document.getElementById('convOperation')?.value||'length',length=document.getElementById('convLengthFields'),section=document.getElementById('convSectionFields'),yieldWrap=document.getElementById('convYieldWrap');if(length)length.style.display=op==='length'?'':'none';if(section)section.style.display=op==='section'?'':'none';if(yieldWrap)yieldWrap.style.display=op==='section'?'':'none'}
function addCutRow(){const box=document.getElementById('convCutRows');if(!box)return;const row=document.createElement('div');row.className='conversion-cut-row';row.dataset.cutRow='';row.innerHTML=`<label><span>Largo (in)</span><input data-cut-length type="number" min="0.125" step="0.125" value="40"></label><label><span>Piezas de este largo</span><input data-cut-qty type="number" min="1" step="1" value="1"></label><button type="button" class="remove-board" data-remove-cut aria-label="Eliminar corte">×</button>`;box.appendChild(row);row.querySelectorAll('input').forEach(x=>x.addEventListener('input',updateConversionPreview));row.querySelector('[data-remove-cut]').addEventListener('click',removeCutRow);updateConversionPreview()}
function removeCutRow(e){const rows=document.querySelectorAll('[data-cut-row]');if(rows.length<=1){toast('Debe quedar al menos un corte.');return}e.currentTarget.closest('[data-cut-row]')?.remove();updateConversionPreview()}
function readCutPattern(){return [...document.querySelectorAll('[data-cut-row]')].map(r=>({lengthIn:Math.max(0,Number(r.querySelector('[data-cut-length]')?.value)||0),qty:Math.max(1,Math.floor(Number(r.querySelector('[data-cut-qty]')?.value)||1))})).filter(c=>c.lengthIn>0)}
function cutPatternSummary(cuts){return cuts.map(c=>`${c.qty}×${c.lengthIn} in`).join(' + ')}
