function productSpecNote(p){
  const top=makeDeckSequence(p.topBoards,p.topSequence),bottom=makeDeckSequence(p.bottomBoards,p.bottomSequence),r=palletTypeRules(p.type);let base='';
  if(r.base==='runner')base=`${p.runners||0} runners${r.notched?' con muescas':''}`;else if(r.base==='block')base=(p.blocks||[]).map(b=>`${b.qty||0} blocks ${b.family}×${b.length}"`).join(', ');else base=`base ${r.entry}: ${p.basePieces||0} runners`;
  const headline=`${p.length}x${p.width} ${base} bottom ${bottom.length} top ${top.length}`;
  const crate=r.base==='crate'?`<div class="small"><b>Crate:</b> el dibujo representa únicamente la tarima base. Plywood, paredes y tapa no se generan todavía.</div>`:'';
  return `<div class="spec-note"><b>Nota de especificación</b><div class="spec-note-main">${headline}</div><div><b>Arriba:</b> ${sequencePositionDescription(top)}.</div><div><b>Abajo:</b> ${sequencePositionDescription(bottom)}.</div>${crate}<div class="small">La descripción prioriza la posición de las tablas para que fabricación pueda seguir el orden de armado.</div></div>`
}
