    const readCurrent=()=>{c.length=Math.max(1,Number(document.getElementById('noLength').value)||1);c.width=Math.max(1,Number(document.getElementById('noWidth').value)||1);c.qty=Math.max(1,Number(document.getElementById('noQty').value)||1);const selectedType=document.getElementById('noType').value,oldRules=palletTypeRules(c.type);if(oldRules.base==='runner')c.runners=Math.max(0,Number(document.getElementById('noRunners')?.value)||0);if(oldRules.base==='crate')c.basePieces=Math.max(0,Number(document.getElementById('noBasePieces')?.value)||0);c.runnerGrade=Number(document.getElementById('noRunnerGrade')?.value)||2;if(oldRules.base==='block'&&document.getElementById('noBlockFamily'))c.blocks=[{family:document.getElementById('noBlockFamily').value,length:Number(document.getElementById('noBlockLength').value)||4,qty:Number(document.getElementById('noBlockQty').value)||9,grade:Number(document.getElementById('noBlockGrade').value)||1}];c.type=selectedType;c.allowConversions={from4x4:false,from4x6:false};c.saveTemplate=Boolean(document.getElementById('noSaveTemplate')?.checked);c.templateName=document.getElementById('noTemplateName')?.value.trim()||'';for(const side of ['top','bottom'])c[side==='top'?'topBoards':'bottomBoards']=[...document.querySelectorAll(`[data-board-side="${side}"] [data-board-row]`)].map(row=>{const sel=row.querySelector('[data-board-family]').value,raw=sel==='__custom__'?row.querySelector('[data-board-custom]').value:sel,fam=canonicalBoardFamily(raw),d=parseFamilyDims(fam)||[1,4];return {family:fam,thickness:d[0],width:d[1],length:Math.max(1,Number(row.querySelector('[data-board-length]').value)||c.width||40),qty:Math.max(0,Number(row.querySelector('[data-board-qty]').value)||0),grade:Number(row.querySelector('[data-board-grade]').value)||2}})};
