function openOrderSpecification(id){const o=orderById(id);if(!o){toast('No encontré esa orden.');return}try{const products=orderProducts(o);const body=products.map((p,i)=>`<section class="spec-product"><div class="section-head"><div><h3>${p.templateName||p.name||`${p.length}×${p.width}`}</h3><p>${p.qty} pallets · ${palletTypeRules(p.type).label}</p></div><span class="pill green">Calidad ${productGradeSummary(p)}</span></div><div class="pallet-preview-grid technical-pair"><div><h4>Vista frontal</h4>${technicalElevationSvg(p,'front')}</div><div><h4>Vista lateral (costado)</h4>${technicalElevationSvg(p,'side')}</div></div><div class="pallet-preview-grid"><div><h4>Vista superior</h4>${palletDrawingSvg(p,'top')}</div><div><h4>Vista inferior</h4>${palletDrawingSvg(p,'bottom')}</div></div>${productSpecNote(p)}</section>`).join('')||'<div class="empty-state">Esta orden no tiene especificación técnica guardada.</div>';openFullDialog(`Especificación · Orden #${o.id}`,`${o.customer}${o.clientOrder?` · Orden cliente ${o.clientOrder}`:''}`,`${body}<div class="dialog-actions"><button type="button" class="btn secondary" id="specClose">Cerrar</button><button type="button" class="btn" id="specPrint">Imprimir hoja de fabricación</button></div>`);document.getElementById('specClose').onclick=closeDialog;document.getElementById('specPrint').onclick=()=>window.print()}catch(err){console.error(err);toast('No se pudo abrir el gráfico. Revisa la especificación de esta orden.')}}

function reserveFinishedPiecesForOrder(order){
  const reqs=finishedPieceRequirements({products:orderProducts(order)}),reservation={};
  for(const req of reqs){let remain=req.count;const matches=(state.lumber||[]).filter(x=>x.category==='finished'&&canonicalBoardFamily(x.family)===canonicalBoardFamily(req.family)&&Number(x.pieceLengthIn)===Number(req.length)&&Number(x.grade)===Number(req.grade)&&availableOf(x)>0).sort((a,b)=>availableOf(b)-availableOf(a));for(const x of matches){if(remain<=0)break;const n=Math.min(remain,availableOf(x));reservation[x.id]=(reservation[x.id]||0)+n;remain-=n}if(remain>0)return false}
  for(const [id,n] of Object.entries(reservation)){const x=lumberById(id);x.reserved=(Number(x.reserved)||0)+n}
  order.materialReservation=reservation;order.requiredPieces=reqs;save();return true
}
function consumeFinishedReservation(order){for(const [id,n] of Object.entries(order.materialReservation||{})){const x=lumberById(id);if(!x)continue;x.qty=Math.max(0,(Number(x.qty)||0)-n);x.reserved=Math.max(0,(Number(x.reserved)||0)-n)}order.materialReservation={};save()}
function startCut(id){const o=orderById(id);if(!o)return;const rows=pieceAvailability({products:orderProducts(o)}),missing=rows.filter(r=>r.missing>0);if(missing.length){toast(`${pieceSizeLabel(missing[0])}: faltan ${missing[0].missing} piezas.`);render();return}if(!reserveFinishedPiecesForOrder(o)){toast('El inventario cambió y ya no alcanza para reservar todas las piezas.');render();return}o.stage='cutting';addNote(`Orden #${o.id}: piezas terminadas reservadas para producción.`);save();toast('Piezas listas reservadas.');render()}
function finishCut(id){const o=orderById(id);if(!o)return;consumeFinishedReservation(o);o.stage='material_ready';addNote(`Orden #${o.id}: piezas listas entregadas a fabricación.`);save();toast('Piezas listas → apareció en Fabricación.');render()}
function startBuild(id){const o=orderById(id);o.stage='building';addNote(`Orden #${o.id}: fabricación iniciada.`);save();toast('Fabricación iniciada.');render()}
function finishBuild(id){const o=orderById(id);o.stage='ready_load';const products=orderProducts(o);if(products.length){for(const p of products){const sku=p.templateName||`${p.length}×${p.width} · ${palletTypeRules(p.type).label}`,f=findFinished(sku);f.qty+=(Number(p.qty)||0);f.reserved+=(Number(p.qty)||0)}}else{const f=findFinished(o.palletSku);f.qty+=o.qty;f.reserved+=o.qty}addNote(`Orden #${o.id}: ${o.qty} pallets terminados → lista para carga.`);save();toast('Fabricación terminada → orden enviada a Carga.');render()}
function openLoadOrder(id){const o=orderById(id);const pickup=o.shipping==='pickup';openDialog(`Pedido #${o.id}`,`${o.customer}${o.clientOrder?` · Cliente ${o.clientOrder}`:''} · ${pickup?'Recogida del cliente':'Envío de fábrica'}`,`<div class="workflow"><span class="step active">1 Verificar</span><span class="step">2 Optimizar / cargar</span><span class="step">3 Evidencia</span><span class="step">4 Firma</span><span class="step">5 Cerrar</span></div><div class="detail-grid"><div class="detail"><b>Producto</b>${o.product}</div><div class="detail"><b>Cantidad</b>${o.qty} pallets</div><div class="detail"><b>Transporte</b>${pickup?'Cliente trae tráiler':'Fábrica pone chofer y tráiler'}</div><div class="detail"><b>Estado</b>${stageLabel(o.stage)}</div></div><div class="stage-actions"><button type="button" class="btn secondary" id="orderLM">Preparar / optimizar carga</button><button type="button" class="btn" id="markLoading">Marcar cargando</button></div><div class="section evidence"><b>Foto / factura firmada</b><p class="small">La foto es opcional, pero se conserva porque normalmente sirve como evidencia de la factura firmada.</p><input id="evidenceFile" type="file" accept="image/*"><div class="evidence-preview" id="evidencePreview">Sin foto seleccionada.</div></div><div class="section form-grid"><label class="wide"><span>Firma / nombre de quien recibe</span><input id="signatureName" placeholder="Nombre o firma registrada"></label><label class="wide"><span>Notas de carga</span><textarea id="loadNotes">${o.notes||''}</textarea></label></div><div class="dialog-actions"><button type="button" class="btn secondary" id="loadCancel">Cerrar</button><button type="button" class="btn" id="finishDispatch">${pickup?'Completar recogida':'Despachar / en tránsito'}</button></div>`);
  document.getElementById('loadCancel').onclick=closeDialog;document.getElementById('orderLM').onclick=()=>openLoadPreparation(o.id);document.getElementById('markLoading').onclick=()=>{o.stage='loading';save();toast('Pedido marcado como cargando.');};document.getElementById('evidenceFile').onchange=e=>{document.getElementById('evidencePreview').textContent=e.target.files[0]?`Foto seleccionada: ${e.target.files[0].name}`:'Sin foto seleccionada.'};document.getElementById('finishDispatch').onclick=()=>{const sig=document.getElementById('signatureName').value.trim();const hasPhoto=Boolean(document.getElementById('evidenceFile').files[0]);o.notes=document.getElementById('loadNotes').value;if(pickup){completeOrder(o,`${sig?'Firma':'Sin firma'}${hasPhoto?' + foto factura':''}`)}else{o.stage='transit';o.evidence=`${sig?'Firma salida':'Sin firma salida'}${hasPhoto?' + foto':''}`;addNote(`Orden #${o.id}: salió de fábrica y está en tránsito.`);save();closeDialog();toast('Pedido en tránsito.');render()}}
}
function completeDelivery(id){const o=orderById(id);completeOrder(o,(o.evidence||'Salida registrada')+' + entrega confirmada')}
function completeOrder(o,evidence){const products=orderProducts(o);if(products.length){for(const p of products){const sku=p.templateName||`${p.length}×${p.width} · ${palletTypeRules(p.type).label}`,f=findFinished(sku);f.qty=Math.max(0,f.qty-(Number(p.qty)||0));f.reserved=Math.max(0,f.reserved-(Number(p.qty)||0))}}else{const f=findFinished(o.palletSku);f.qty=Math.max(0,f.qty-o.qty);f.reserved=Math.max(0,f.reserved-o.qty)}state.history.unshift({id:o.id,clientOrder:o.clientOrder||'',customer:o.customer,shipping:o.shipping,completed:'Hoy',evidence:evidence||'Registro completado'});state.orders=state.orders.filter(x=>x.id!==o.id);addNote(`Orden #${o.id}: completada y enviada al historial.`);save();closeDialog();toast('Orden completada → Historial.');render()}
function openLoadPreparation(id){
  const o=orderById(id);if(!o)return;const items=loadItemsFor(o);if(!items.length){toast('Esta orden no tiene medidas válidas para LoadMaster.');return}
  const rows=items.map((x,i)=>`<tr data-prep-row="${i}"><td><b>${x.name||`${x.length}×${x.width}`}</b><div class="small">${palletTypeRules(x.type).label}</div></td><td><input class="qty-locked" type="number" value="${Number(x.quantity)||1}" readonly></td><td><input data-prep-height type="number" min="1" value="${Math.max(1,Number(x.maxHeight)||palletTypeRules(x.type).maxHeight)}"></td><td><b>${palletTypeRules(x.type).canRotate?'Sí':'No'}</b><div class="small">Automático por tipo</div></td></tr>`).join('');
  openDialog(`Preparar carga #${o.id}`,`${o.customer} · ${loadTotal(items)} pallets`,`<div class="notification info"><b>Datos conectados.</b> Cantidad, tipo y giro vienen de la orden. Aquí solo ajustas la altura máxima si esta carga necesita una excepción.</div><div class="prep-trailer"><label><span>Ancho tráiler (in)</span><input id="prepTrailerWidth" type="number" value="${Number(o.trailerWidth)||96}"></label><label><span>Largo tráiler (in)</span><input id="prepTrailerLength" type="number" value="${Number(o.trailerLength)||628}"></label></div><div class="table-wrap prep-table"><table><thead><tr><th>Medida / tipo</th><th>Cantidad</th><th>Máximo por pila</th><th>Giro</th></tr></thead><tbody>${rows}</tbody></table></div><div class="dialog-actions"><button class="btn secondary" id="prepCancel">Volver</button><button class="btn" id="prepLaunch">Abrir LoadMaster a pantalla completa</button></div>`);
  document.getElementById('prepCancel').onclick=()=>{closeDialog();openLoadOrder(id)};document.getElementById('prepLaunch').onclick=()=>{const prepared=items.map((item,i)=>{const row=document.querySelector(`[data-prep-row="${i}"]`),rules=palletTypeRules(item.type);return {...item,quantity:Number(item.quantity)||1,maxHeight:Math.max(1,Number(row.querySelector('[data-prep-height]').value)||rules.maxHeight),canRotate:rules.canRotate,type:item.type}});o.loadItems=clone(prepared);o.trailerWidth=Math.max(1,Number(document.getElementById('prepTrailerWidth').value)||96);o.trailerLength=Math.max(1,Number(document.getElementById('prepTrailerLength').value)||628);save();localStorage.setItem('loadmaster-theme',state.settings.theme||'system');localStorage.setItem(LM_HANDOFF,JSON.stringify({version:2,source:'Pallet Operations',orderId:o.id,customer:o.customer,shipping:o.shipping,trailer:{width:o.trailerWidth,length:o.trailerLength},items:prepared,returnUrl:'index.html#carga',createdAt:new Date().toISOString()}));window.location.href=`loadmaster.html?platform=1&order=${encodeURIComponent(o.id)}`}
}
function openLoadMaster(){
  const payload={version:1,source:'Pallet Operations',orderId:'manual',customer:'Carga manual',trailer:{width:96,length:628},items:[],returnUrl:'index.html#carga',createdAt:new Date().toISOString()};
  localStorage.setItem('loadmaster-theme',state.settings.theme||'system');localStorage.setItem(LM_HANDOFF,JSON.stringify(payload));window.location.href='loadmaster.html?platform=1';
}

document.querySelectorAll('.nav-btn').forEach(b=>b.addEventListener('click',()=>navigate(b.dataset.view)));
document.getElementById('menuBtn').addEventListener('click',()=>document.getElementById('sidebar').classList.toggle('open'));
document.getElementById('themeQuick')?.addEventListener('change',e=>setTheme(e.target.value));document.getElementById('dialogThemeQuick')?.addEventListener('change',e=>setTheme(e.target.value));window.matchMedia?.('(prefers-color-scheme: dark)').addEventListener?.('change',()=>{if(state.settings.theme==='system')applyTheme()});
document.getElementById('resetDemo').addEventListener('click',()=>{if(confirm('¿Restablecer todos los datos del prototipo?')){state=normalizeState(structuredClone(initialState));save();toast('Demo restablecida.');render()}});
if(!views[currentView])currentView='inicio';
applyTheme();render();
